		if (!collection) return buildNotFoundSeo(pathname, "Collection Not Found (404) – BUILDsmore Luxury Real Estate");
		const canonical = `${PRODUCTION_DOMAIN}/collection/${encodeURIComponent(collection.slug)}`;
