			ogDescription: description,
			ogUrl: canonical,
			ogImage,
			ogImageAlt: collection.title,
			twitterCard: "summary_large_image",
			twitterTitle: title,
			twitterDescription: description,
			twitterImage: ogImage,
			isNotFound: false,
			breadcrumbs,
			structuredData
